# AI Office v2.6 Part C Memory Retrieval Relevance Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found." }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v2.6-part-c-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
function Write-EmbeddedFile {
    param([string]$RelativePath,[string]$Base64Content)

    $Destination = Join-Path $Repository $RelativePath
    $Parent = Split-Path -Parent $Destination

    if ($Parent) {
        New-Item -ItemType Directory -Path $Parent -Force | Out-Null
    }

    if (Test-Path -LiteralPath $Destination -PathType Leaf) {
        $BackupPath = Join-Path $BackupDirectory $RelativePath
        $BackupParent = Split-Path -Parent $BackupPath

        if ($BackupParent) {
            New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null
        }

        Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
    }

    [IO.File]::WriteAllBytes(
        $Destination,
        [Convert]::FromBase64String($Base64Content)
    )

    Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\memory\retrieval-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\memory\Get-AIOfficeMemorySearchTokens.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\memory\Get-AIOfficeMemoryRelevanceScore.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\memory\Search-AIOfficeMemory.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\memory\Show-AIOfficeMemorySearch.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\memory\Test-AIOfficeMemoryRetrievalRelevance.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.6-Part-C-Memory-Retrieval-Relevance.md" -Base64Content ""
$Scripts = Get-ChildItem "E:\AI\AI-Office\scripts\memory\*.ps1" -File
foreach ($Script in $Scripts) {
  $Tokens=$null; $ParseErrors=$null
  [System.Management.Automation.Language.Parser]::ParseFile($Script.FullName,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
  if ($ParseErrors.Count -gt 0) {
    throw ("Syntax error in " + $Script.FullName + ": " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; "))
  }
}
Write-Host ""
Write-Host "AI Office v2.6 Part C Memory Retrieval & Relevance installed successfully." -ForegroundColor Green
Write-Host "Relevant-memory search is available; live conversation injection remains disabled." -ForegroundColor Cyan
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan